		public void Initialize()
		{

			if (!string.IsNullOrEmpty(update_option.ReceiveUdpPort))// open UDP
			{
				receiver = new UdpReceiver<PacketToDSViz>();
				//receiver.Open(30001);
				int port_num = 30001;
				try
				{
					port_num = int.Parse(update_option.ReceiveUdpPort);
					receiver.Open(port_num);
				}
				catch
				{
					// Udp Open failed.
					UnityEngine.Debug.LogWarning("UDP is not opened.");
				}
			}

			// open ShareMem
			if (!string.IsNullOrEmpty(update_option.ReceiveSharememName))
			{
				// 
				shrMem = new SharedMemoryManager<PacketToDSViz>();
				shrMem.CreateMemory(update_option.ReceiveSharememName, update_option.ReceiveSharememName + "Mutex");
			}
		}

