		// Getting data 
		public PacketToDSViz[] GetDataFromExternal()
		{
			PacketToDSViz[] ret = null;
			
			if(string.IsNullOrEmpty(update_option.ReceiveSharememName))
			{
				// Get from UDP
				if(!string.IsNullOrEmpty(update_option.ReceiveUdpPort))
				{
					if (receiver!= null &&  receiver.isOpen())
					{
						ret = receiver.GetAll(PacketToDSViz.heading);
					}
				}
			}
			else
			{
				// Get From Shared Memory
				ret = new PacketToDSViz[1];

				shrMem.ReadData(ref ret[0]);

				//return ret;
			}

			return ret;
		}

		// update info from communication devices
		public void Update()
		{
			
			//PacketToDSViz data = receiver.Get();
			PacketToDSViz[] data_all = GetDataFromExternal();

			PacketToDSViz data = default(PacketToDSViz);

			if (data_all == null || data_all.Length == 0)
			{
				if (receiver != null && receiver.isOpen())
				{
					data = receiver.GetLast();
				}
			}
			else
			{
				// record to log
				if (log_timer.IsRunning)
				{
					for (int i = 0; i < data_all.Length; i++)
					{
						PacketToDSVizLog log_item = new PacketToDSVizLog();
						log_item.data = data_all[i];
						log_item.receive_time_in_ms = log_timer.ElapsedMilliseconds;
						log_item.simulation_time_in_ms = log_item.receive_time_in_ms;
						log_data.Add(log_item);
					}
				}

				data = data_all[data_all.Length - 1];
			}

			if (IsReplaying()) data = GetFromLog();

			DSGlobal.current_car_states = data;

			// objects setting
			for (int i = 0; i < data.num_of_car_data; i++)
			{
				int trg_car_id = data.car_states [i].id;

				// set car position and orientation; 
				// Modify DSParam.TransformCoordinateXYZ to change 
				// coordinate system; this is a kind of parameter.
				Vector3 pos = DSParam.TransformCoordinateXYZ(
						data.car_states[i].x,
						data.car_states[i].y,
						data.car_states[i].z + (float)0.1 
					);
				Quaternion ori = DSParam.TransformCoordinateYPR(
					data.car_states[i].yaw - (float)Math.PI/2,
					data.car_states[i].pitch,
					data.car_states[i].roll
					);

				// Find Car Script
				objman.CheckCar(trg_car_id);

                var car_updater = objman.cars[trg_car_id].gameObject.GetComponentInChildren<IDSCarUpdater>();

                WinkerState ws = objman.cars[trg_car_id].gameObject.GetComponentInChildren<WinkerState>();
                if (ws != null)
                {
                    ws.winkers = data.car_states[i].winkers;
                }

                // update position from host side
                objman.SetCarPosition(trg_car_id, pos, ori);
				if (car_updater != null) {
                    try
                    {
                        car_updater.UpdateByDSInfo(trg_car_id, data.car_states[i]);
                    }
                    catch
                    {

                    }
				}

				int mesh = data.car_states[i].mesh_id;

				// set mesh
				objman.SetCarMesh(trg_car_id, mesh);
				//objman.SetCarMesh(i, data.car_states[i].mesh_id);

			}

			/*// camera setting
			camera_attached_car_id = data.GetCamera(0).camera_attached_car_id;
			try {
				//var script = camera_master.GetComponent<CameraMaster3Scr>() as CameraMaster3Scr;
				//script.obj_to_follow = objman.cars[camera_attached_car_id];
				DSGlobal.camera_master.transform.parent =
					objman.cars[camera_attached_car_id].transform;

			}catch
			{

			}*/

			// put received data to Global;
			DSGlobal.current_car_states = data;

			
		}

		public bool IsRecording()
		{
			return log_timer.IsRunning;
		}

		public void StartRecording(string filename)
		{
			if (log_data!=null)log_data.Clear();
			log_data = new List<PacketToDSVizLog>();
			log_timer.Reset();
			log_timer.Start();
			log_data_file = filename;
		}

		public void StopRecording()
		{
			log_timer.Stop();
			if(log_data != null && log_data.Count>0)
				SaveRecords();
		}

		public bool IsReplaying()
		{
			return rep_timer.IsRunning;
		}

		public void StartReplay(string filename)
		{
			log_data_file = filename;
			LoadRecords();
			rep_timer.Reset();
			rep_timer.Start();
		}

		public void StopReplay()
		{
			rep_timer.Stop();
		}

		private PacketToDSViz GetFromLog()
		{
			long current_time = rep_timer.ElapsedMilliseconds;

			int index = log_data.FindLastIndex(o => o.receive_time_in_ms < current_time);

			if (index == -1) return new PacketToDSViz(0);

			return log_data[index].data;
		}

		private float Rad2Deg( float rad)
		{
			return (float)(rad / Math.PI * 180f);
		}
