		}
		private float Deg2Rad( float deg)
		{
			return (float)(deg * Math.PI / 180f);
		}
		private double Deg2Rad(double deg)
		{
			return (deg * Math.PI / 180);
		}

		[Serializable()]
		public class PacketToDSVizLog
		{
			public long receive_time_in_ms;
			public long simulation_time_in_ms;
			public PacketToDSViz data;
		}

		private void SaveRecords()
		{
			FileStream fs = new FileStream(log_data_file,
				FileMode.Create,
				FileAccess.Write);
			BinaryFormatter bf = new BinaryFormatter();
			//シリアル化して書き込む
			bf.Serialize(fs, log_data);
			fs.Close();
		}

		private void LoadRecords()
		{
			FileStream fs = new FileStream(log_data_file,
				FileMode.Open,
				FileAccess.Read);
			BinaryFormatter bf = new BinaryFormatter();
			//シリアル化して書き込む
			log_data = (List<PacketToDSVizLog>)bf.Deserialize(fs);
			fs.Close();
		}

